<script setup>
import { reactive, computed, ref, watch } from 'vue'
import { db, api, reportsView } from '../domain/store.js'
import StatusTag from './StatusTag.vue'
const props=defineProps({type:String,id:String,stationId:String,rowId:String})
const emit=defineEmits(['done','cancel'])
const existing=props.type==='stations'?db.stations.find(s=>s.id===props.id):props.type==='devices'?db.devices.find(d=>d.id===props.id):props.type==='rows'?db.rows.find(r=>r.id===props.id):null
const rate=props.type==='rates'?db.rates.find(r=>r.stationId===props.id):null
const report=computed(()=>reportsView.value.find(r=>r.id===props.id))
const selectedStation=existing?.stationId||props.stationId||db.stations[0]?.id||''
const form=reactive({name:existing?.name||'',address:existing?.address||'',scene:existing?.scene||'校园',lat:existing?.lat??'',lng:existing?.lng??'',note:existing?.note||'',code:existing?.code||'',stationId:selectedStation,rowId:existing?.rowId||props.rowId||db.rows.find(r=>r.stationId===selectedStation)?.id||'',position:existing?.position||'',portCount:2,deviceCount:props.type==='batch'?1:12,electricRate:rate?.electricRate??.6,serviceRate:rate?.serviceRate??.2,resolution:report.value?.resolution||''})
const error=ref(''),stationName=computed(()=>db.stations.find(s=>s.id===props.id)?.name),availableRows=computed(()=>db.rows.filter(r=>r.stationId===form.stationId)),batchRow=computed(()=>db.rows.find(r=>r.id===props.rowId))
watch(()=>form.stationId,()=>{form.rowId=db.rows.find(r=>r.stationId===form.stationId)?.id||'';form.position=''})
function save(){error.value='';try{if(props.type==='stations')api.saveStation(form,props.id);if(props.type==='devices')api.saveDevice(form,props.id);if(props.type==='rows')api.saveRow(form,props.id);if(props.type==='batch')api.addDevicesToRow(props.rowId,form.deviceCount);if(props.type==='rates')api.saveRate(props.id,form.electricRate,form.serviceRate);if(props.type==='reports')api.resolveReport(props.id,form.resolution);emit('done')}catch(e){error.value=e.message}}
</script>
<template><form class="entity-form" @submit.prevent="save">
 <p v-if="error" class="form-error" role="alert">{{error}}</p>
 <template v-if="type==='stations'"><label>站点名称 <b>*</b><input v-model="form.name" required maxlength="60" placeholder="例如：图书馆示例站"/></label><label>应用场景 <b>*</b><select v-model="form.scene"><option>校园</option><option>住宅小区</option><option>园区</option><option>其他集中停车场所</option></select></label><label class="full-field">地址 <b>*</b><input v-model="form.address" required maxlength="160" placeholder="填写集中停车棚的具体位置"/></label><label>纬度（GCJ-02）<b>*</b><input v-model="form.lat" type="number" required step="any" min="-90" max="90"/></label><label>经度（GCJ-02）<b>*</b><input v-model="form.lng" type="number" required step="any" min="-180" max="180"/></label><label class="full-field">站点说明<textarea v-model="form.note" maxlength="400" rows="3"/></label><p class="form-hint full-field">站点建立后，可新增 A 排、B 排等设备排，再在每排添加双插座设备。默认电费 0.60 元/度、服务费 0.20 元/度，可单独修改。</p></template>
 <template v-else-if="type==='devices'"><label>设备编号 <b>*</b><input v-model="form.code" required maxlength="30" placeholder="例如：EB-0201"/></label><label>设备名称 <b>*</b><input v-model="form.name" required maxlength="60" placeholder="例如：A排13号设备"/></label><label>所属站点 <b>*</b><select v-model="form.stationId" required><option v-for="s in db.stations" :key="s.id" :value="s.id">{{s.name}}</option></select></label><label>所属设备排 <b>*</b><select v-model="form.rowId" required><option value="" disabled>请先新增设备排</option><option v-for="row in availableRows" :key="row.id" :value="row.id">{{row.name}}</option></select></label><label>排内序号<input v-model.number="form.position" type="number" min="1" step="1" placeholder="留空则追加到本排末尾"/></label><label>设备规格<input value="双插座设备：A / B 两个独立插座" readonly aria-label="设备规格"/></label><p class="form-hint full-field">一台设备固定两个插座；需要增加充电位置时，追加设备或新增设备排。正在充电或异常占用的设备不能移动位置。</p></template>
 <template v-else-if="type==='rows'"><label>所属站点 <b>*</b><select v-model="form.stationId" :disabled="!!id" required><option v-for="s in db.stations" :key="s.id" :value="s.id">{{s.name}}</option></select></label><label>设备排名称 <b>*</b><input v-model="form.name" required maxlength="30" placeholder="例如：C排 / 东侧第2排"/></label><label v-if="!id">本排初始设备数 <b>*</b><input v-model.number="form.deviceCount" type="number" required min="1" max="100" step="1"/></label><div v-if="!id" class="row-capacity-preview"><strong>{{Number(form.deviceCount)||0}} 台 × 2 插座</strong><span>合计 {{(Number(form.deviceCount)||0)*2}} 个插座</span></div><p class="form-hint full-field">一排常用十几台设备，可填写实际数量，之后也能逐台或批量追加。站点内可以建立多排，设备编号会自动生成。</p></template>
 <template v-else-if="type==='batch'"><p class="form-hint full-field">向 {{db.stations.find(s=>s.id===batchRow?.stationId)?.name}} · {{batchRow?.name}} 追加双插座设备。</p><label>追加设备数量 <b>*</b><input v-model.number="form.deviceCount" type="number" required min="1" max="100" step="1"/></label><div class="row-capacity-preview"><strong>新增 {{Number(form.deviceCount)||0}} 台设备</strong><span>增加 {{(Number(form.deviceCount)||0)*2}} 个独立插座</span></div><p class="form-hint full-field">自动按本排末尾继续编号，每台都包含 A、B 两个插座。已有设备和历史订单保持不变。</p></template>
 <template v-else-if="type==='rates'"><p class="form-hint full-field">站点：{{stationName}}。以下费率仅影响之后开始的订单。</p><label>电费单价（元/度）<b>*</b><input v-model.number="form.electricRate" type="number" required min="0" step="0.01"/></label><label>服务费单价（元/度）<b>*</b><input v-model.number="form.serviceRate" type="number" required min="0" step="0.01"/></label><p class="form-hint full-field">按本次模拟电量分别计算电费与服务费，分项四舍五入到分后相加。</p></template>
 <template v-else-if="type==='reports'"><div class="full-field report-context"><StatusTag :text="report.status==='pending'?'待处理':'已处理'"/><p>{{report.socket?.station?.name}} / {{report.socket?.code}}</p><p>{{report.description}}</p><small>提交人：{{report.user?.name}} · {{report.createdAt}}</small></div><label class="full-field">处理说明 <b>*</b><textarea v-model="form.resolution" required rows="4" maxlength="500" :readonly="report.status==='resolved'" placeholder="填写检查结果、处理措施及后续安排"/></label><p v-if="report.resolvedAt" class="form-hint full-field">处理时间：{{report.resolvedAt}}</p><p class="form-hint full-field">保存处理结果不会自动恢复插座故障，请在设备页面单独核验。</p></template>
 <footer class="form-actions full-field"><button class="outline-button" type="button" @click="emit('cancel')">取消</button><button v-if="!(type==='reports'&&report?.status==='resolved')" class="soft-button active" type="submit">{{type==='reports'?'保存处理结果':type==='batch'?'确认追加':'保存'}}</button></footer>
</form></template>
